-- p1 apply body, copied unchanged from 01-named-fixes/apply.sql.
DO $do$ DECLARE n int; BEGIN
UPDATE "QuestionBankItem" q SET question=COALESCE(p.question,q.question), scenario=COALESCE(p.scenario,q.scenario), options=CASE WHEN p.opts IS NOT NULL THEN ((q.options::jsonb - 'distractorRationale' - 'keyTakeaways' - 'segments' - 'clinicalReasoning') || jsonb_build_object('options',p.opts,'clinicalReasoning',p.clin))::text ELSE q.options END, "correctAnswer"=COALESCE(p.correct,q."correctAnswer"), explanation=p.expl, "references"=p.refs, "updatedAt"=now(), curation_meta=COALESCE(q.curation_meta,'{}'::jsonb)||jsonb_build_object('naplexSprint',jsonb_build_object('pkg','P1','date','2026-10-30'))
FROM jsonb_to_recordset($pl$[{"id":"cmra7vbdt004w1y3ewz30krtr","old_md5":"aa240bebfeb26a360f5457880470d1f6","question":"The emergency physician asks the pharmacist for the best initial recommendation. Which should the pharmacist recommend?","scenario":"A 30-year-old man with alcohol use disorder comes to the emergency department after 2 days of vomiting and abdominal pain. Serum K+ is 2.8 mEq/L with metabolic alkalosis; magnesium has not resulted. His ECG shows no arrhythmia. His only medication is lorazepam 0.5 mg as needed.","opts":["Give diluted IV potassium chloride with ECG monitoring and check magnesium","Start a scheduled lorazepam taper and recheck the potassium level tomorrow","Give potassium chloride concentrate by rapid IV push over 5 minutes","Hold potassium replacement until an abdominal CT has been completed"],"correct":"Give diluted IV potassium chloride with ECG monitoring and check magnesium","expl":"K+ 2.8 mEq/L with vomiting needs prompt replacement. IV potassium chloride must be diluted; the label caps the rate at 10 mEq/h when K+ is above 2.5 mEq/L unless the patient is on continuous ECG monitoring with severe hypokalemia. Alcohol use disorder and vomiting make magnesium deficiency likely, and low magnesium makes hypokalemia refractory, so magnesium is checked and replaced at the same time. Concentrate by push is never given. CT does not need to precede treatment, and lorazepam tapering is not the priority. Hypokalemia and the alkalosis here fit vomiting-related loss.\n\n## Sources\n- Potassium chloride injection concentrate FDA-approved labeling (DailyMed setid fcd4f458-ce27-417e-9bb6-de1cc49d44b9): must be diluted; when K >2.5 mEq/L do not exceed 10 mEq/h; faster rates only with continuous ECG monitoring in severe hypokalemia\n- Kardalas E, et al. Hypokalemia: a clinical update. Endocr Connect 2018;7(4):R135-R146 (doi:10.1530/EC-18-0109)","clin":"K+ 2.8 mEq/L with vomiting needs prompt replacement. IV potassium chloride must be diluted; the label caps the rate at 10 mEq/h when K+ is above 2.5 mEq/L unless the patient is on continuous ECG monitoring with severe hypokalemia. Alcohol use disorder and vomiting make magnesium deficiency likely, and low magnesium makes hypokalemia refractory, so magnesium is checked and replaced at the same time. Concentrate by push is never given. CT does not need to precede treatment, and lorazepam tapering is not the priority. Hypokalemia and the alkalosis here fit vomiting-related loss.","refs":[{"label":"Potassium chloride injection concentrate FDA-approved labeling (DailyMed setid fcd4f458-ce27-417e-9bb6-de1cc49d44b9): must be diluted; when K >2.5 mEq/L do not exceed 10 mEq/h; faster rates only with continuous ECG monitoring in severe hypokalemia"},{"label":"Kardalas E, et al. Hypokalemia: a clinical update. Endocr Connect 2018;7(4):R135-R146 (doi:10.1530/EC-18-0109)"}]},{"id":"cmr7sbvmg00181y2vsbjypz8k","old_md5":"96f9fcac5b8a64bbe11681b5e1989d2e","question":"Which medication should be given first for this patient?","scenario":null,"opts":["Sublingual nitroglycerin 0.4 mg","Clopidogrel 600 mg orally","Metoprolol tartrate 50 mg orally","Chewed aspirin 162 to 325 mg"],"correct":"Chewed aspirin 162 to 325 mg","expl":"ST elevation in II, III and aVF is an inferior STEMI. The guideline calls for aspirin 162 to 325 mg as soon as possible, chewed if the tablet is not enteric coated. P2Y12 therapy and reperfusion follow. Nitroglycerin treats ischemic pain but is not a first antiplatelet, and inferior infarcts can involve the right ventricle, where preload reduction can drop blood pressure (guideline wording on nitrates in RV involvement not read this session: unverified). An oral beta-blocker is not the first drug.\n\n## Sources\n- 2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Patients With Acute Coronary Syndromes. Circulation 2025 (doi:10.1161/CIR.0000000000001309); J Am Coll Cardiol (doi:10.1016/j.jacc.2024.11.009)","clin":"ST elevation in II, III and aVF is an inferior STEMI. The guideline calls for aspirin 162 to 325 mg as soon as possible, chewed if the tablet is not enteric coated. P2Y12 therapy and reperfusion follow. Nitroglycerin treats ischemic pain but is not a first antiplatelet, and inferior infarcts can involve the right ventricle, where preload reduction can drop blood pressure (guideline wording on nitrates in RV involvement not read this session: unverified). An oral beta-blocker is not the first drug.","refs":[{"label":"2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Patients With Acute Coronary Syndromes. Circulation 2025 (doi:10.1161/CIR.0000000000001309); J Am Coll Cardiol (doi:10.1016/j.jacc.2024.11.009)"}]},{"id":"cmrm22k1h000x1yshd85zlmd7","old_md5":"941ce46c50ad365ef94c802d1cb2c1e5","question":"Which medication change is most appropriate to reduce his risk of falls and confusion?","scenario":"An 82-year-old man with hypertension, osteoarthritis and mild cognitive impairment has taken lorazepam 1 mg nightly for 3 years, plus lisinopril and ibuprofen. He presents with new confusion and two falls this month.","opts":["Discontinue ibuprofen and keep lorazepam at the current dose","Gradually taper lorazepam with prescriber follow-up","Discontinue lorazepam abruptly starting tonight","Add calcium and vitamin D to reduce fracture risk"],"correct":"Gradually taper lorazepam with prescriber follow-up","expl":"Benzodiazepines are on the Beers list to avoid in older adults because they raise the risk of cognitive impairment, delirium and falls. After 3 years of nightly use the patient is physically dependent, and the FDA boxed warning states that abrupt discontinuation or too-rapid dose reduction can cause serious withdrawal, so the answer is a gradual, patient-specific taper. The NSAID also deserves review (ACE inhibitor plus NSAID in an older adult), but it is less tied to confusion and falls. Calcium does not address the cause. No taper schedule is given in the item because none was verified.\n\n## Sources\n- American Geriatrics Society 2023 updated AGS Beers Criteria for potentially inappropriate medication use in older adults. J Am Geriatr Soc 2023;71(7):2052-2081 (doi:10.1111/jgs.18372)\n- FDA Drug Safety Communication, 23 Sep 2020: Boxed Warning updated for the benzodiazepine class (abrupt discontinuation or too-rapid dose reduction can cause serious withdrawal; patient-specific gradual taper)","clin":"Benzodiazepines are on the Beers list to avoid in older adults because they raise the risk of cognitive impairment, delirium and falls. After 3 years of nightly use the patient is physically dependent, and the FDA boxed warning states that abrupt discontinuation or too-rapid dose reduction can cause serious withdrawal, so the answer is a gradual, patient-specific taper. The NSAID also deserves review (ACE inhibitor plus NSAID in an older adult), but it is less tied to confusion and falls. Calcium does not address the cause. No taper schedule is given in the item because none was verified.","refs":[{"label":"American Geriatrics Society 2023 updated AGS Beers Criteria for potentially inappropriate medication use in older adults. J Am Geriatr Soc 2023;71(7):2052-2081 (doi:10.1111/jgs.18372)"},{"label":"FDA Drug Safety Communication, 23 Sep 2020: Boxed Warning updated for the benzodiazepine class (abrupt discontinuation or too-rapid dose reduction can cause serious withdrawal; patient-specific gradual taper)"}]},{"id":"cmr0qcbhr005n1y9axb0jveim","old_md5":"1efcf3fcb47d641a84425adf25d60029","question":"According to KDIGO 2022 dosing guidance, which is the most appropriate action regarding his metformin?","scenario":"A 60-year-old man with type 2 diabetes has taken metformin 1000 mg twice daily for 4 years. His eGFR, previously 52, is now 38 mL/min/1.73 m2 and stable on repeat. He also takes lisinopril and atorvastatin and reports occasional GI upset.","opts":["Increase to 1500 mg twice daily and monitor eGFR every 3 to 6 months","Continue 1000 mg twice daily and monitor eGFR every 3 to 6 months","Reduce to 500 mg twice daily and monitor eGFR every 3 to 6 months","Stop metformin and monitor eGFR every 3 to 6 months"],"correct":"Reduce to 500 mg twice daily and monitor eGFR every 3 to 6 months","expl":"The label says to reassess benefit and risk when eGFR falls below 45 and to stop below 30; it does not require stopping at 38. KDIGO 2022 advises halving the dose (maximum half the usual maximum, so about 1000 mg/day) at eGFR 30 to 44 and monitoring kidney function every 3 to 6 months. Raising the dose or leaving it unchanged ignores the fall in clearance; stopping is not required until eGFR is below 30.\n\n## Sources\n- FDA-approved metformin hydrochloride tablets labeling, section 2.3 (e.g., DailyMed setid bb62088f-e9af-4644-9f57-cb90bab0f199): contraindicated eGFR <30; initiation not recommended at 30-45; if eGFR falls below 45 assess benefit/risk of continuing\n- KDIGO 2022 Clinical Practice Guideline for Diabetes Management in Chronic Kidney Disease. Kidney Int 2022;102(5S) (doi:10.1016/j.kint.2022.06.008)","clin":"The label says to reassess benefit and risk when eGFR falls below 45 and to stop below 30; it does not require stopping at 38. KDIGO 2022 advises halving the dose (maximum half the usual maximum, so about 1000 mg/day) at eGFR 30 to 44 and monitoring kidney function every 3 to 6 months. Raising the dose or leaving it unchanged ignores the fall in clearance; stopping is not required until eGFR is below 30.","refs":[{"label":"FDA-approved metformin hydrochloride tablets labeling, section 2.3 (e.g., DailyMed setid bb62088f-e9af-4644-9f57-cb90bab0f199): contraindicated eGFR <30; initiation not recommended at 30-45; if eGFR falls below 45 assess benefit/risk of continuing"},{"label":"KDIGO 2022 Clinical Practice Guideline for Diabetes Management in Chronic Kidney Disease. Kidney Int 2022;102(5S) (doi:10.1016/j.kint.2022.06.008)"}]},{"id":"cmr0mle46000q1y3490phnae0","old_md5":"ec23606aacac13fa2b0d90be297d2364","question":"Which is the most appropriate reversal strategy?","scenario":"A 68-year-old woman with atrial fibrillation takes warfarin. She presents to the ED with severe headache and confusion. CT shows an acute subdural hematoma. INR is 4.5.","opts":["Four-factor prothrombin complex concentrate plus intravenous vitamin K","Intravenous vitamin K 10 mg and repeat the INR in 6 hours","Hold the next warfarin dose and recheck the INR in 24 hours","Fresh frozen plasma 15 mL/kg, then repeat the INR in 6 hours"],"correct":"Four-factor prothrombin complex concentrate plus intravenous vitamin K","expl":"Warfarin-associated intracranial hemorrhage with INR 2.0 or higher needs immediate reversal without waiting for repeat labs. 4F-PCC corrects the INR within minutes but its effect fades; IV vitamin K (5 to 10 mg) is given with it to restore clotting-factor synthesis. Vitamin K alone is too slow, waiting is unsafe, and 4F-PCC is preferred over plasma. The guideline text is written for spontaneous ICH; a subdural bleed on warfarin is managed by the same reversal principle, but confirm that extrapolation with the clinical reviewer (unverified).\n\n## Sources\n- 2022 AHA/ASA Guideline for the Management of Patients With Spontaneous Intracerebral Hemorrhage. Stroke 2022 (doi:10.1161/STR.0000000000000407)","clin":"Warfarin-associated intracranial hemorrhage with INR 2.0 or higher needs immediate reversal without waiting for repeat labs. 4F-PCC corrects the INR within minutes but its effect fades; IV vitamin K (5 to 10 mg) is given with it to restore clotting-factor synthesis. Vitamin K alone is too slow, waiting is unsafe, and 4F-PCC is preferred over plasma. The guideline text is written for spontaneous ICH; a subdural bleed on warfarin is managed by the same reversal principle, but confirm that extrapolation with the clinical reviewer (unverified).","refs":[{"label":"2022 AHA/ASA Guideline for the Management of Patients With Spontaneous Intracerebral Hemorrhage. Stroke 2022 (doi:10.1161/STR.0000000000000407)"}]},{"id":"cmshjhax4000e1yspzhhgi60e","old_md5":"1ac993b33f71d2ff7adcd74cf6a2427f","question":"Which action is most appropriate before dispensing this prescription?","scenario":"A pharmacy receives a handwritten prescription that reads 'Clon 0.1 mg, 1 tab BID, #60' for a 58-year-old man whose profile lists hypertension and generalized anxiety. No indication is written and the prescriber's office is open.","opts":["Dispense clonidine because he has hypertension","Dispense clonazepam because he has anxiety","Ask the patient which tablet he has taken before and dispense that","Call the office to confirm which drug was intended"],"correct":"Call the office to confirm which drug was intended","expl":"An abbreviated name that fits two drugs with confusable names (cloNIDine, clonazePAM; both with a plausible indication in this profile) cannot be resolved by guessing from the diagnosis list. The pharmacist confirms the intended drug and indication with the prescriber and documents it. ISMP lists the pair as confused and recommends tall-man lettering in practice systems. Dispensing from the diagnosis or asking the patient to pick a tablet are not safe verification.\n\n## Sources\n- ISMP List of Confused Drug Names (2023 PDF) and FDA/ISMP Look-Alike Drug Names with Recommended Tall Man Letters: cloNIDine / clonazePAM listed as a confused pair","clin":"An abbreviated name that fits two drugs with confusable names (cloNIDine, clonazePAM; both with a plausible indication in this profile) cannot be resolved by guessing from the diagnosis list. The pharmacist confirms the intended drug and indication with the prescriber and documents it. ISMP lists the pair as confused and recommends tall-man lettering in practice systems. Dispensing from the diagnosis or asking the patient to pick a tablet are not safe verification.","refs":[{"label":"ISMP List of Confused Drug Names (2023 PDF) and FDA/ISMP Look-Alike Drug Names with Recommended Tall Man Letters: cloNIDine / clonazePAM listed as a confused pair"}]},{"id":"cmshi6sg3000w1y29myjdx6d8","old_md5":"026c17fe90df9c790edabc85c804e29e","question":"What is the pharmacist's best next step?","scenario":"A 66-year-old man is admitted with pneumonia. The pharmacist has interviewed him and his daughter and reviewed his outpatient fill history, which show lisinopril 20 mg daily. The admission orders omit lisinopril with no documented reason.","opts":["Add lisinopril to the orders to match the home medication list","Leave the orders as written because admission sets are standard","Contact the admitting prescriber to ask whether the omission is intentional","Ask the patient to resume lisinopril from his home supply"],"correct":"Contact the admitting prescriber to ask whether the omission is intentional","expl":"After the best possible medication history is gathered from the patient and at least one other source, an unexplained omission is treated as a discrepancy that only the prescriber can resolve. The pharmacist asks whether the omission was intentional, the order is changed only if the prescriber agrees, and the result is documented. Ordering a drug independently or ignoring the home list is unsafe; repeating a completed interview delays resolution.\n\n## Sources\n- The Joint Commission National Patient Safety Goal NPSG.03.06.01 (maintain and communicate accurate patient medication information; resolve omissions, duplications, contraindications, unclear information)","clin":"After the best possible medication history is gathered from the patient and at least one other source, an unexplained omission is treated as a discrepancy that only the prescriber can resolve. The pharmacist asks whether the omission was intentional, the order is changed only if the prescriber agrees, and the result is documented. Ordering a drug independently or ignoring the home list is unsafe; repeating a completed interview delays resolution.","refs":[{"label":"The Joint Commission National Patient Safety Goal NPSG.03.06.01 (maintain and communicate accurate patient medication information; resolve omissions, duplications, contraindications, unclear information)"}]},{"id":"cmros03zl001x1yok8cg1xwed","old_md5":"d0c0f6ed1b76d2644352bcbea3349a8f","question":"What should the pharmacist do first to resolve this discrepancy?","scenario":null,"opts":["Record both hydrochlorothiazide and furosemide as active medications","Confirm with the patient which diuretic is taken, using the bottle","Stop both diuretics until the prescriber clarifies","Assume the more recently prescribed diuretic is the one in use"],"correct":"Confirm with the patient which diuretic is taken, using the bottle","expl":"The first step in reconciliation is a best possible medication history from the patient and at least one other source. Listing both drugs risks therapeutic duplication, stopping both leaves her hypertension untreated, and assuming the newest prescription is current guesses. If the sources still conflict, the pharmacist then clarifies with the prescriber.\n\n## Sources\n- The Joint Commission National Patient Safety Goal NPSG.03.06.01 (maintain and communicate accurate patient medication information; resolve omissions, duplications, contraindications, unclear information)","clin":"The first step in reconciliation is a best possible medication history from the patient and at least one other source. Listing both drugs risks therapeutic duplication, stopping both leaves her hypertension untreated, and assuming the newest prescription is current guesses. If the sources still conflict, the pharmacist then clarifies with the prescriber.","refs":[{"label":"The Joint Commission National Patient Safety Goal NPSG.03.06.01 (maintain and communicate accurate patient medication information; resolve omissions, duplications, contraindications, unclear information)"}]},{"id":"cmr0mwumu005u1y34d17ywgi8","old_md5":"9d67e5485f93a56eb5506e90b3c19481","question":"Which counseling point is most important?","scenario":null,"opts":["Report the new thirst and frequent urination to the prescriber soon","Take metformin with meals to reduce GI side effects","Check blood glucose daily and bring the log to the next routine visit","Avoid alcohol while taking metformin because of lactic acidosis risk"],"correct":"Report the new thirst and frequent urination to the prescriber soon","expl":"Thirst, polyuria and fatigue on metformin signal possible loss of glycemic control, so he needs prompt evaluation (glucose and A1c) and, if confirmed, a change in therapy. Food, alcohol and routine home glucose checks are less urgent than reporting the symptoms. Glucose monitoring can support evaluation, but it does not replace it.\n\n## Sources\n- American Diabetes Association Standards of Care in Diabetes-2026, Section 7 Diabetes Technology. Diabetes Care 2026;49(Suppl 1):S150 (doi:10.2337/dc26-s007)","clin":"Thirst, polyuria and fatigue on metformin signal possible loss of glycemic control, so he needs prompt evaluation (glucose and A1c) and, if confirmed, a change in therapy. Food, alcohol and routine home glucose checks are less urgent than reporting the symptoms. Glucose monitoring can support evaluation, but it does not replace it.","refs":[{"label":"American Diabetes Association Standards of Care in Diabetes-2026, Section 7 Diabetes Technology. Diabetes Care 2026;49(Suppl 1):S150 (doi:10.2337/dc26-s007)"}]},{"id":"cmr4j6rb3001j1ygk3d8iub8e","old_md5":"28d2c408e968b8a262e93fb20e7b5531","question":"Which action should the pharmacist take first?","scenario":null,"opts":["Recommend increasing the sertraline dose and reassess in 4 weeks","Assess adherence and suicidal thoughts, then involve the prescriber","Suggest an over-the-counter antihistamine sleep aid at bedtime","Refer him to a mental health clinic and close the consultation"],"correct":"Assess adherence and suicidal thoughts, then involve the prescriber","expl":"Worsening anxiety and insomnia on an SSRI can come from missed doses, activation early in treatment, caffeine or substances, or clinical worsening; the labeling directs monitoring for anxiety, agitation, panic attacks, insomnia and suicidal thoughts. The pharmacist cannot raise the dose, and a sleep aid hides the problem. Referral is appropriate but follows a brief assessment that tells the prescriber what changed.\n\n## Sources\n- Sertraline (Zoloft) FDA-approved labeling, Warnings: Suicidal thoughts and behaviors / clinical worsening (monitor for anxiety, agitation, panic attacks, insomnia, irritability) (DailyMed setid c3b0b1f8-abfd-4054-8645-fd076305f4f8)","clin":"Worsening anxiety and insomnia on an SSRI can come from missed doses, activation early in treatment, caffeine or substances, or clinical worsening; the labeling directs monitoring for anxiety, agitation, panic attacks, insomnia and suicidal thoughts. The pharmacist cannot raise the dose, and a sleep aid hides the problem. Referral is appropriate but follows a brief assessment that tells the prescriber what changed.","refs":[{"label":"Sertraline (Zoloft) FDA-approved labeling, Warnings: Suicidal thoughts and behaviors / clinical worsening (monitor for anxiety, agitation, panic attacks, insomnia, irritability) (DailyMed setid c3b0b1f8-abfd-4054-8645-fd076305f4f8)"}]},{"id":"cmros04ee00211yokmeq6u7pc","old_md5":"a285eb591e608a5275f2900b79ce1275","question":null,"scenario":null,"opts":null,"correct":null,"expl":"This is an unverified, remote, non-anaphylactic penicillin history (a delayed itchy rash in childhood, no hives, swelling, wheeze or hypotension). The 2022 AAAAI/ACAAI drug allergy practice parameter states that such patients can receive any cephalosporin routinely, without skin testing or extra precautions. Cefadroxil is therefore appropriate with routine counseling, and the pharmacist updates the allergy record with the reaction details. Switching to a non-beta-lactam is unnecessary, antihistamine premedication is not recommended, and lifelong avoidance of all beta-lactams is wrong.\n\n## Sources\n- Khan DA, et al. Drug allergy: a 2022 practice parameter update. J Allergy Clin Immunol 2022;150(6):1333-1393 (doi:10.1016/j.jaci.2022.08.028)","clin":"This is an unverified, remote, non-anaphylactic penicillin history (a delayed itchy rash in childhood, no hives, swelling, wheeze or hypotension). The 2022 AAAAI/ACAAI drug allergy practice parameter states that such patients can receive any cephalosporin routinely, without skin testing or extra precautions. Cefadroxil is therefore appropriate with routine counseling, and the pharmacist updates the allergy record with the reaction details. Switching to a non-beta-lactam is unnecessary, antihistamine premedication is not recommended, and lifelong avoidance of all beta-lactams is wrong.","refs":[{"label":"Khan DA, et al. Drug allergy: a 2022 practice parameter update. J Allergy Clin Immunol 2022;150(6):1333-1393 (doi:10.1016/j.jaci.2022.08.028)"}]},{"id":"cmrorqphl00041yokjywzmgz7","old_md5":"21a70068d19879c69bee4f422913f0ee","question":"How can the antacid affect itraconazole capsules, and what should the pharmacist recommend?","scenario":"A 58-year-old man with hypertension takes lisinopril and uses calcium carbonate antacid tablets for heartburn. His dermatologist prescribes itraconazole capsules for toenail onychomycosis.","opts":["It decreases absorption; give the antacid 1 hour before or 2 hours after","It increases absorption; both can be taken at the same time","It has no effect on absorption, so no timing change is needed","It decreases absorption; give the antacid 30 minutes before or after"],"correct":"It decreases absorption; give the antacid 1 hour before or 2 hours after","expl":"Itraconazole capsules need an acidic stomach to dissolve and absorb. Antacids raise gastric pH, lowering absorption, so the labeling advises taking the antacid at least 1 hour before or 2 hours after itraconazole (some labels say 2 hours either side). Taking them together reduces antifungal exposure.\n\n## Sources\n- Itraconazole capsules FDA-approved labeling (DailyMed setid 31735974-a7ac-42b5-8ce1-4d8dc2808c3a): acid-neutralizing medicines (antacids) at least 1 hour before or 2 hours after itraconazole; some current labels say 2 hours before or after","clin":"Itraconazole capsules need an acidic stomach to dissolve and absorb. Antacids raise gastric pH, lowering absorption, so the labeling advises taking the antacid at least 1 hour before or 2 hours after itraconazole (some labels say 2 hours either side). Taking them together reduces antifungal exposure.","refs":[{"label":"Itraconazole capsules FDA-approved labeling (DailyMed setid 31735974-a7ac-42b5-8ce1-4d8dc2808c3a): acid-neutralizing medicines (antacids) at least 1 hour before or 2 hours after itraconazole; some current labels say 2 hours before or after"}]},{"id":"cmr4edxdz003t1yk37bjn2ajl","old_md5":"e75a3d00f6f5722c5926927c5b92cfe7","question":null,"scenario":null,"opts":null,"correct":null,"expl":"The bupropion label warns that it can raise blood pressure and advises checking BP before starting and monitoring periodically. Seizure risk is also dose related, so doses are increased gradually. Weight is a less immediate concern, bupropion is not a serotonergic agent so serotonin syndrome is not the main monitoring issue, and routine liver tests are not required.\n\n## Sources\n- Bupropion hydrochloride tablets FDA-approved labeling (DailyMed setid 334e5635-e4cc-cf2a-e063-6294a90ae1e1; also FDA label 018644s064, rev 11/2025): seizure risk is dose related; can raise blood pressure, check BP before starting and monitor periodically","clin":"The bupropion label warns that it can raise blood pressure and advises checking BP before starting and monitoring periodically. Seizure risk is also dose related, so doses are increased gradually. Weight is a less immediate concern, bupropion is not a serotonergic agent so serotonin syndrome is not the main monitoring issue, and routine liver tests are not required.","refs":[{"label":"Bupropion hydrochloride tablets FDA-approved labeling (DailyMed setid 334e5635-e4cc-cf2a-e063-6294a90ae1e1; also FDA label 018644s064, rev 11/2025): seizure risk is dose related; can raise blood pressure, check BP before starting and monitor periodically"}]},{"id":"cmsfjapv400081yms128u5ldf","old_md5":"fc5224cb0919124267c06b1b4b6416f9","question":"Which approach is most likely to improve the dissolution of this poorly water-soluble drug?","scenario":null,"opts":["Immediate-release tablet containing the coarse crystalline drug","Extended-release capsule with a hydrophobic polymer matrix","Micronized formulation that increases the surface area exposed to fluid","Enteric-coated tablet that releases drug in the small intestine"],"correct":"Micronized formulation that increases the surface area exposed to fluid","expl":"Dissolution rate rises with surface area (Noyes-Whitney), so reducing particle size speeds dissolution of a poorly soluble drug. Extended-release designs slow release, and enteric coating delays release to the intestine without improving dissolution.\n\n## Sources\n- Noyes AA, Whitney WR. The rate of solution of solid substances in their own solutions. J Am Chem Soc 1897;19(12):930-934 (doi:10.1021/ja02086a003)","clin":"Dissolution rate rises with surface area (Noyes-Whitney), so reducing particle size speeds dissolution of a poorly soluble drug. Extended-release designs slow release, and enteric coating delays release to the intestine without improving dissolution.","refs":[{"label":"Noyes AA, Whitney WR. The rate of solution of solid substances in their own solutions. J Am Chem Soc 1897;19(12):930-934 (doi:10.1021/ja02086a003)"}]},{"id":"cmr80qoix001j1yjnfiqt6uv4","old_md5":"87ee06c5c450b2d4d922ca96f2f85918","question":"Which counseling point is most important?","scenario":"A 55-year-old woman with COPD (FEV1 60% predicted) receives a new prescription for tiotropium capsules for use with a HandiHaler. She uses albuterol as needed and fluticasone/salmeterol.","opts":["Swallow one capsule each morning with a full glass of water","Pierce the capsule in the device and inhale its contents once daily","Inhale one capsule whenever she feels short of breath","Inhale two capsules together each morning for added effect"],"correct":"Pierce the capsule in the device and inhale its contents once daily","expl":"Tiotropium capsules are for inhalation only and are used with the HandiHaler; swallowing them is a known error. Tiotropium is maintenance therapy and not a rescue drug; albuterol remains her rescue inhaler. The label advises care with narrow-angle glaucoma and urinary retention.\n\n## Sources\n- SPIRIVA HandiHaler (tiotropium) FDA-approved labeling (DailyMed setid 820839ef-e53d-47e8-a3b9-d911ff92e6a9): capsules for inhalation only, do not swallow; maintenance not rescue; caution narrow-angle glaucoma and urinary retention","clin":"Tiotropium capsules are for inhalation only and are used with the HandiHaler; swallowing them is a known error. Tiotropium is maintenance therapy and not a rescue drug; albuterol remains her rescue inhaler. The label advises care with narrow-angle glaucoma and urinary retention.","refs":[{"label":"SPIRIVA HandiHaler (tiotropium) FDA-approved labeling (DailyMed setid 820839ef-e53d-47e8-a3b9-d911ff92e6a9): capsules for inhalation only, do not swallow; maintenance not rescue; caution narrow-angle glaucoma and urinary retention"}]},{"id":"cmr4fwi6x004a1yroyencxdt1","old_md5":"d9c5b834b4b9187ce0cc1583012ce8c4","question":"Which counseling point is most important?","scenario":null,"opts":["Hold empagliflozin and call the prescriber if vomiting or poor oral intake occurs","Take empagliflozin at bedtime to avoid urinary frequency during the day","Expect your blood glucose to drop within minutes of each dose","Stop metformin, since empagliflozin makes it unnecessary for glucose control"],"correct":"Hold empagliflozin and call the prescriber if vomiting or poor oral intake occurs","expl":"The labeling warns of ketoacidosis (which can occur with normal glucose), volume depletion and genital and urinary tract infections. Teaching patients to stop and call during acute illness addresses the first two. Dosing is in the morning, glucose effect is gradual, and metformin is generally continued.\n\n## Sources\n- JARDIANCE (empagliflozin) FDA-approved labeling, Warnings (FDA label 204629s063, rev 10/2025): ketoacidosis (assess regardless of glucose), volume depletion, genitourinary infections","clin":"The labeling warns of ketoacidosis (which can occur with normal glucose), volume depletion and genital and urinary tract infections. Teaching patients to stop and call during acute illness addresses the first two. Dosing is in the morning, glucose effect is gradual, and metformin is generally continued.","refs":[{"label":"JARDIANCE (empagliflozin) FDA-approved labeling, Warnings (FDA label 204629s063, rev 10/2025): ketoacidosis (assess regardless of glucose), volume depletion, genitourinary infections"}]},{"id":"cmshg6q0i001y1yft25u0888l","old_md5":"401cd50dd1e141e011afde79e0248efb","question":"Which question best applies the teach-back method?","scenario":null,"opts":["Does my explanation make sense to you?","Do you understand how to take your medication?","Are you clear on the dose and timing of this medicine?","Can you tell me how you will take this medicine at home?"],"correct":"Can you tell me how you will take this medicine at home?","expl":"Teach-back asks the patient to explain the information in his or her own words so the pharmacist can check whether the explanation was clear. Yes/no questions such as 'Do you understand?' or 'Any questions?' do not test understanding.\n\n## Sources\n- AHRQ Health Literacy Universal Precautions Toolkit, Tool 5: Use the Teach-Back Method (ahrq.gov/health-literacy/improve/precautions/tool5.html)","clin":"Teach-back asks the patient to explain the information in his or her own words so the pharmacist can check whether the explanation was clear. Yes/no questions such as 'Do you understand?' or 'Any questions?' do not test understanding.","refs":[{"label":"AHRQ Health Literacy Universal Precautions Toolkit, Tool 5: Use the Teach-Back Method (ahrq.gov/health-literacy/improve/precautions/tool5.html)"}]},{"id":"cmr4itdnw004f1y7u7to1kbt1","old_md5":"16353923d8adbcaa605a345acc054599","question":"Which action is most appropriate for his metformin?","scenario":"A 60-year-old man with type 2 diabetes takes metformin 500 mg twice daily and atorvastatin 20 mg daily. His serum creatinine is 1.8 mg/dL and his eGFR is 43 mL/min/1.73 m2, unchanged on repeat testing. He feels well and is concerned about his kidney function.","opts":["Stop metformin and start basal insulin glargine","Continue metformin at the current dose and monitor eGFR","Increase metformin to 1,000 mg twice daily with meals","Replace metformin with glipizide 5 mg once daily"],"correct":"Continue metformin at the current dose and monitor eGFR","expl":"Metformin decisions are based on eGFR, not serum creatinine. The metformin label contraindicates use below an eGFR of 30, does not recommend starting it at 30 to 45, and asks the prescriber to assess the benefit and risk of continuing when eGFR falls below 45. ADA Standards of Care 2026 (section 11) gives the same eGFR-based guidance. At an eGFR of 43 this stable patient on 1,000 mg/day can continue the current dose with periodic eGFR monitoring. Stopping is not required above an eGFR of 30, and increasing the dose is not supported because KDIGO 2022 advises dose reduction at an eGFR of 30 to 44. Switching to a sulfonylurea adds hypoglycemia risk without a reason.\n\n## Sources\n- FDA-approved metformin hydrochloride tablets labeling, section 2.3 Recommendations for Use in Renal Impairment (DailyMed setid 8cd5555c-f6b2-28d8-e053-2a95a90a5f1e)\n- American Diabetes Association Professional Practice Committee. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes-2026. Diabetes Care 2026;49(Suppl 1):S246 (doi:10.2337/dc26-s011)\n- KDIGO 2022 Clinical Practice Guideline for Diabetes Management in Chronic Kidney Disease. Kidney Int 2022;102(5S) (doi:10.1016/j.kint.2022.06.008)","clin":"Metformin decisions are based on eGFR, not serum creatinine. The metformin label contraindicates use below an eGFR of 30, does not recommend starting it at 30 to 45, and asks the prescriber to assess the benefit and risk of continuing when eGFR falls below 45. ADA Standards of Care 2026 (section 11) gives the same eGFR-based guidance. At an eGFR of 43 this stable patient on 1,000 mg/day can continue the current dose with periodic eGFR monitoring. Stopping is not required above an eGFR of 30, and increasing the dose is not supported because KDIGO 2022 advises dose reduction at an eGFR of 30 to 44. Switching to a sulfonylurea adds hypoglycemia risk without a reason.","refs":[{"label":"FDA-approved metformin hydrochloride tablets labeling, section 2.3 Recommendations for Use in Renal Impairment (DailyMed setid 8cd5555c-f6b2-28d8-e053-2a95a90a5f1e)"},{"label":"American Diabetes Association Professional Practice Committee. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes-2026. Diabetes Care 2026;49(Suppl 1):S246 (doi:10.2337/dc26-s011)"},{"label":"KDIGO 2022 Clinical Practice Guideline for Diabetes Management in Chronic Kidney Disease. Kidney Int 2022;102(5S) (doi:10.1016/j.kint.2022.06.008)"}]},{"id":"cmr7ugsow00151yt3cpldkcqn","old_md5":"0e51f3282384a7cd3246747dd06f3787","question":"According to GOLD 2026, which medication should be added to his current regimen?","scenario":"A 58-year-old man with COPD and no features of asthma has been maintained on fluticasone/salmeterol 250/50 mcg, one inhalation twice daily. In the past year he had one moderate exacerbation treated with prednisone, and his blood eosinophil count is 250 cells/uL. He still has exertional dyspnea and uses albuterol more than twice a week despite good inhaler technique and adherence. He also takes lisinopril and atorvastatin.","opts":["Montelukast 10 mg once daily","Theophylline extended-release twice daily","Tiotropium inhalation powder once daily","Roflumilast 500 mcg once daily"],"correct":"Tiotropium inhalation powder once daily","expl":"GOLD 2026 states that a patient with COPD and no features of asthma who is on LABA+ICS and has further exacerbations should be escalated to LABA+LAMA+ICS when the blood eosinophil count is 100 cells/uL or higher, and switched to LABA+LAMA when it is below 100. For major symptoms the change is to LABA+LAMA or LABA+LAMA+ICS depending on the earlier response to ICS. This patient has an exacerbation and an eosinophil count of 250 cells/uL, so adding the long-acting anticholinergic tiotropium to fluticasone/salmeterol gives LABA+LAMA+ICS. GOLD says the evidence does not support leukotriene modifiers in COPD, and roflumilast is considered only for persistent exacerbations on LABA+LAMA+ICS in patients with FEV1 below 50%, chronic bronchitis and a prior severe exacerbation. Theophylline is not part of the GOLD escalation pathway for this patient.\n\n## Sources\n- Global Initiative for Chronic Obstructive Lung Disease. Global Strategy for the Diagnosis, Management and Prevention of COPD, 2026 Report, Chapter 3, follow-up pharmacological treatment: patients on treatment with LABA+ICS (goldcopd.org/2026-gold-report-and-pocket-guide/)","clin":"GOLD 2026 states that a patient with COPD and no features of asthma who is on LABA+ICS and has further exacerbations should be escalated to LABA+LAMA+ICS when the blood eosinophil count is 100 cells/uL or higher, and switched to LABA+LAMA when it is below 100. For major symptoms the change is to LABA+LAMA or LABA+LAMA+ICS depending on the earlier response to ICS. This patient has an exacerbation and an eosinophil count of 250 cells/uL, so adding the long-acting anticholinergic tiotropium to fluticasone/salmeterol gives LABA+LAMA+ICS. GOLD says the evidence does not support leukotriene modifiers in COPD, and roflumilast is considered only for persistent exacerbations on LABA+LAMA+ICS in patients with FEV1 below 50%, chronic bronchitis and a prior severe exacerbation. Theophylline is not part of the GOLD escalation pathway for this patient.","refs":[{"label":"Global Initiative for Chronic Obstructive Lung Disease. Global Strategy for the Diagnosis, Management and Prevention of COPD, 2026 Report, Chapter 3, follow-up pharmacological treatment: patients on treatment with LABA+ICS (goldcopd.org/2026-gold-report-and-pocket-guide/)"}]},{"id":"cmra6ltbk000k1ybjys03owcn","old_md5":"51eb7ff5da50af8263f57bd2d6e5df66","question":"Which counseling point about her fluticasone/salmeterol Diskus is correct?","scenario":"A 45-year-old woman with asthma picks up a refill of albuterol. She also takes montelukast and a fluticasone/salmeterol dry powder inhaler (Diskus) 250/50 mcg, one inhalation twice daily, and asks how to use the Diskus correctly. She has no known drug allergies.","opts":["Attach a spacer to the Diskus to improve drug delivery","Rinse her mouth with water and spit it out after each dose","Take an extra inhalation when wheezing starts instead of albuterol","Stop the Diskus once she has been symptom free for a week"],"correct":"Rinse her mouth with water and spit it out after each dose","expl":"The labeling directs patients to rinse the mouth with water without swallowing after each inhalation to reduce the risk of oropharyngeal candidiasis. The Diskus is a twice-daily maintenance inhaler: extra doses must not be used for acute symptoms, which are treated with a short-acting beta2-agonist, and it is not stopped when symptoms improve. The Diskus delivers dry powder and must not be used with a spacer.\n\n## Sources\n- ADVAIR DISKUS (fluticasone propionate and salmeterol inhalation powder) FDA-approved labeling, sections 2, 5.2 and 5.4 (DailyMed setid 4eeb5f6a-593f-4a9e-9692-adefa2caf8fc)\n- ADVAIR DISKUS Medication Guide and Instructions for Use: do not use the Diskus with a spacer; rinse the mouth with water and spit it out after each dose (DailyMed setid 7c9c722b-68ac-4bda-ad99-50e3fb1c58c8)","clin":"The labeling directs patients to rinse the mouth with water without swallowing after each inhalation to reduce the risk of oropharyngeal candidiasis. The Diskus is a twice-daily maintenance inhaler: extra doses must not be used for acute symptoms, which are treated with a short-acting beta2-agonist, and it is not stopped when symptoms improve. The Diskus delivers dry powder and must not be used with a spacer.","refs":[{"label":"ADVAIR DISKUS (fluticasone propionate and salmeterol inhalation powder) FDA-approved labeling, sections 2, 5.2 and 5.4 (DailyMed setid 4eeb5f6a-593f-4a9e-9692-adefa2caf8fc)"},{"label":"ADVAIR DISKUS Medication Guide and Instructions for Use: do not use the Diskus with a spacer; rinse the mouth with water and spit it out after each dose (DailyMed setid 7c9c722b-68ac-4bda-ad99-50e3fb1c58c8)"}]}]$pl$::jsonb) AS p(id text, old_md5 text, question text, scenario text, opts jsonb, correct text, expl text, clin text, refs jsonb)
WHERE q.id=p.id AND q."fieldId"='pharmacy' AND md5(q.explanation)=p.old_md5 AND jsonb_typeof(q.options::jsonb)='object';
GET DIAGNOSTICS n = ROW_COUNT;
IF n <> 20 THEN RAISE EXCEPTION 'P1 fixes (v2 wording): expected 20 rows, got %', n; END IF;
END $do$;

DO $do$ DECLARE n int; BEGIN
UPDATE "QuestionBankItem" q SET explanation=p.expl, "references"=p.refs, "updatedAt"=now(), curation_meta=COALESCE(q.curation_meta,'{}'::jsonb)||jsonb_build_object('naplexSprint',jsonb_build_object('pkg','P1','date','2026-10-30'))
FROM jsonb_to_recordset($pl$[{"id":"cmrovuyoo000c1yu3xnnykipd","old_md5":"d0d91b6e86595721511bb8b807f53fa2","expl":"Alendronate should be taken with plain water on an empty stomach to ensure optimal absorption. Other beverages and food can interfere with its absorption, reducing efficacy.\n\nWhy correct: Taking alendronate with plain water on an empty stomach maximizes absorption and therapeutic effect.\n\nPearl: Alendronate requires specific administration to ensure efficacy.\n\nMemory hook: Alendronate AM: Alone with water, no food.\n\nSteps: 1. Review the patient's current administration method. 2. Educate on the correct administration with water on an empty stomach. 3. Advise waiting 30 minutes before eating or drinking anything else.\n\nNext: Follow up to ensure the patient adheres to the administration guidelines and monitor for efficacy.\n\nTakeaway: Proper administration of alendronate is crucial for maximizing absorption and therapeutic benefit.\n\n## Sources\n- Alendronate sodium (Fosamax) FDA-approved labeling, section 2.6 Important Administration Instructions (DailyMed setid 14e931fd-2c5f-4d90-b7db-5980706f4a56)","refs":[{"label":"Alendronate sodium (Fosamax) FDA-approved labeling, section 2.6 Important Administration Instructions (DailyMed setid 14e931fd-2c5f-4d90-b7db-5980706f4a56)"}]}]$pl$::jsonb) AS p(id text, old_md5 text, expl text, refs jsonb)
WHERE q.id=p.id AND q."fieldId"='pharmacy' AND md5(q.explanation)=p.old_md5;
GET DIAGNOSTICS n = ROW_COUNT;
IF n <> 1 THEN RAISE EXCEPTION 'P1 cite-only (3xnnykipd): expected 1 rows, got %', n; END IF;
END $do$;

DO $do$ DECLARE n int; BEGIN
UPDATE "QuestionBankItem" q SET active=false, "updatedAt"=now(), curation_meta=COALESCE(q.curation_meta,'{}'::jsonb)||jsonb_build_object('naplexSprint',jsonb_build_object('pkg','P1','date','2026-10-30'))
FROM jsonb_to_recordset($pl$[{"id":"cmqvlh4fv00171y745ijian72","old_active":true},{"id":"cmrlhabol00071yf3p44ab0jv","old_active":true}]$pl$::jsonb) AS p(id text, old_active boolean)
WHERE q.id=p.id AND q."fieldId"='pharmacy' AND q.active=p.old_active;
GET DIAGNOSTICS n = ROW_COUNT;
IF n <> 2 THEN RAISE EXCEPTION 'P1 hides (active=false): expected 2 rows, got %', n; END IF;
END $do$;

DO $do$ DECLARE n int; BEGIN
UPDATE "QuestionBankItem" q SET "subjectId"=p.new_sub, "updatedAt"=now(), curation_meta=COALESCE(q.curation_meta,'{}'::jsonb)||jsonb_build_object('naplexSprint',jsonb_build_object('pkg','P1','date','2026-10-30'))
FROM jsonb_to_recordset($pl$[{"id":"cmr062ltj005b1yhothxwdmxw","old_sub":"compounding-calculations","new_sub":"cardiovascular-rx"},{"id":"cmr7td8z600191y4g9f54g92p","old_sub":"compounding-calculations","new_sub":"otc-self-care"}]$pl$::jsonb) AS p(id text, old_sub text, new_sub text)
WHERE q.id=p.id AND q."fieldId"='pharmacy' AND q."subjectId"=p.old_sub;
GET DIAGNOSTICS n = ROW_COUNT;
IF n <> 2 THEN RAISE EXCEPTION 'P1 subject tags: expected 2 rows, got %', n; END IF;
END $do$;
